steps.code:
const d = json(input) || {}, now = d.this || {}, was = d.last || {};
return Object.keys(now).map(k => {
  const a = Number(now[k]), b = Number(was[k]);
  const change = Number.isFinite(b) && b !== 0 ? ((a - b) / Math.abs(b) * 100).toFixed(1) + '%' : 'no figure last week';
  return k + ': ' + a + ' (last week ' + (Number.isFinite(b) ? b : '-') + ', ' + change + ')';
}).join('\n') || 'No numbers in the brief.';

